with p as (
  insert into public.projects (slug, title, category, location, summary, overview, concept, requirements, materials, cover_image, is_sample, featured, sort_order) values
  ('emerald-penthouse-living', 'The Emerald Penthouse', 'Living Rooms', 'Nairobi, Kenya',
   'A sculptural living room built around emerald velvet, book-matched marble and soft brass light.',
   'A sample concept for a penthouse living room designed for entertaining and quiet evenings alike. The layout opens the room to the view while anchoring it with a single statement wall.',
   'Deep emerald upholstery is balanced against pale stone and warm metal, so the room feels rich without feeling heavy. Lighting is layered from cove, pendant and accent sources.',
   'Generous seating for guests, a calm palette for everyday living, and a focal wall that holds the room together.',
   array['Calacatta-style marble','Emerald velvet','Brushed champagne brass','Wool and silk rug','Oak flooring'],
   '/__l5e/assets-v1/846cde70-88a4-4a0e-8feb-3fde3d2ae76c/hero-living-room.jpg', true, true, 1),
  ('velvet-master-suite', 'Velvet Master Suite', 'Bedrooms', 'Nairobi, Kenya',
   'A restful master suite with an upholstered emerald headboard and a spa-like ensuite.',
   'A sample bedroom concept focused on rest: soft textures, controlled light and a quiet, hotel-like ensuite.',
   'The upholstered headboard becomes the architecture of the room, framed by warm bedside lighting and layered linen.',
   'A calm sleeping environment, generous storage and an ensuite that feels like a private retreat.',
   array['Emerald velvet headboard','Linen bedding','Brass wall lights','Marble ensuite','Zellige tile'],
   '/__l5e/assets-v1/03b84f2b-1b85-473f-9b19-59dc114b99e8/project-bedroom.jpg', true, true, 2),
  ('marble-brass-kitchen', 'Marble and Brass Kitchen', 'Kitchens', 'Nairobi, Kenya',
   'Lacquered emerald cabinetry, a marble island and champagne brass details for a kitchen made for gathering.',
   'A sample kitchen concept that blends a working family kitchen with an elegant space for hosting.',
   'A single marble island anchors the room while emerald lacquer and brass hardware bring depth and warmth.',
   'Durable surfaces, generous preparation space, concealed storage and seating at the island.',
   array['Marble island','Emerald lacquer cabinetry','Brass hardware','Pendant lighting'],
   '/__l5e/assets-v1/fdf408b1-f180-4c48-9c89-239520424a0f/project-kitchen.jpg', true, true, 3),
  ('boutique-hotel-lobby', 'Boutique Hotel Lobby', 'Hospitality', 'Kenya',
   'An arrival space with emerald armchairs, a statement chandelier and a calm sense of welcome.',
   'A sample hospitality concept for a boutique hotel arrival and lounge area.',
   'First impressions are shaped by scale, light and texture: a statement chandelier, intimate seating groups and natural stone.',
   'Clear guest flow, comfortable waiting areas and a memorable, photographable arrival moment.',
   array['Statement chandelier','Emerald upholstery','Natural stone','Brass detailing'],
   '/__l5e/assets-v1/015c6549-6f2a-4d43-bb76-a505e82140c0/project-hotel-lobby.jpg', true, true, 4),
  ('executive-office-suite', 'Executive Office Suite', 'Office', 'Nairobi, Kenya',
   'A refined executive office with walnut joinery, a marble feature wall and emerald leather seating.',
   'A sample office concept that balances focused work with a welcoming space for client meetings.',
   'Warm walnut and pale marble create a confident backdrop, while emerald leather adds character.',
   'A practical workstation, a meeting corner, integrated storage and controlled daylight.',
   array['Walnut joinery','Marble feature wall','Emerald leather','Brass accents'],
   '/__l5e/assets-v1/c146fcc8-997d-4366-8290-bf1291542659/project-office.jpg', true, false, 5),
  ('emerald-lounge-restaurant', 'The Emerald Lounge', 'Commercial', 'Kenya',
   'A restaurant and bar lounge with curved velvet banquettes, terrazzo floors and a glowing fluted bar.',
   'A sample commercial concept for an upscale restaurant and lounge.',
   'Curved banquettes create intimacy, while a fluted brass bar becomes the glowing heart of the room.',
   'Efficient service flow, flexible seating, durable finishes and evening atmosphere.',
   array['Emerald velvet banquettes','Terrazzo flooring','Fluted brass bar','Marble tables'],
   '/__l5e/assets-v1/1ea328c5-65ce-4a4c-82e9-8d516a04b885/project-restaurant.jpg', true, false, 6),
  ('grand-salon-residence', 'The Grand Salon', 'Residential', 'Kenya',
   'A formal salon with a tufted emerald sofa, crystal chandelier and marble and gold wall panels.',
   'A residential living space presented as a sample of a classic, formal design direction.',
   'Classic panelling and crystal light are paired with a tufted emerald sofa for a timeless, formal look.',
   'A formal room for receiving guests with a strong sense of symmetry.',
   array['Tufted emerald velvet','Crystal chandelier','Marble and gold panels','Gold pedestal table'],
   '/__l5e/assets-v1/ec571f49-0758-4bc1-8aa3-76976b11375c/project-grand-salon.jpg', true, false, 7),
  ('open-plan-family-home', 'Open-Plan Family Home', 'Residential', 'Kenya',
   'A bright open-plan living and kitchen space with marble floors and an emerald sectional.',
   'A residential open-plan space presented as a sample of a contemporary family home.',
   'Light marble floors keep the space open and bright while the emerald sectional defines the living zone.',
   'Clear zones for living, cooking and dining within one connected space.',
   array['Marble flooring','Emerald velvet sectional','Gold chandelier','Marble kitchen island'],
   '/__l5e/assets-v1/f4a5e6ff-9a06-4f53-a749-dced85fd5e7d/project-open-plan.jpg', true, false, 8)
  returning id, slug
)
insert into public.project_images (project_id, url, caption, sort_order)
select p.id, g.url, g.caption, g.sort_order from p join (values
  ('emerald-penthouse-living', '/__l5e/assets-v1/baa8916a-6b32-40ca-9e5f-0e7f7d6952d9/project-curved-sofa.jpg', 'Curved velvet seating and marble feature wall', 1),
  ('emerald-penthouse-living', '/__l5e/assets-v1/f829ae9c-bda0-4c80-b2ee-8aee4d31f28e/service-lighting.jpg', 'Layered evening lighting', 2),
  ('velvet-master-suite', '/__l5e/assets-v1/924be52e-ec1b-4032-bd2e-2ff67ae73be2/project-bathroom.jpg', 'Marble ensuite with emerald zellige niche', 1),
  ('marble-brass-kitchen', '/__l5e/assets-v1/993c9196-c581-4ea7-8291-8972a457def3/project-dining.jpg', 'Adjoining formal dining room', 1),
  ('boutique-hotel-lobby', '/__l5e/assets-v1/1ea328c5-65ce-4a4c-82e9-8d516a04b885/project-restaurant.jpg', 'Lounge and bar concept', 1),
  ('executive-office-suite', '/__l5e/assets-v1/0345e923-fb9c-49d4-bb91-e05743c85ef0/service-3d-visualization.jpg', '3D visualisation in progress', 1),
  ('emerald-lounge-restaurant', '/__l5e/assets-v1/015c6549-6f2a-4d43-bb76-a505e82140c0/project-hotel-lobby.jpg', 'Arrival lounge', 1),
  ('grand-salon-residence', '/__l5e/assets-v1/993c9196-c581-4ea7-8291-8972a457def3/project-dining.jpg', 'Formal dining', 1),
  ('open-plan-family-home', '/__l5e/assets-v1/fdf408b1-f180-4c48-9c89-239520424a0f/project-kitchen.jpg', 'Kitchen detail', 1)
) as g(slug, url, caption, sort_order) on g.slug = p.slug;